    const w = word(s).padEnd(CELLS, ' ')
    if (last && last.word === w) return last.markup
    const prev = !last || (s.mode === 'requesting' && last.word !== w) ? ' '.repeat(CELLS) : last.word
    const { body, end } = cells(w, prev, o, LETTERS)
