    const flash = s.mode === 'thinking'
      ? `<animate attributeName="opacity" values="1;0.35" keyTimes="0;0.6" calcMode="discrete" dur="1.4s" begin="${ms(end)}" repeatCount="indefinite"/>` : ''
    const width = (CELLS - 1) * o.pitch + o.cw + 2 * o.inset
