  key: "dotmatrix",
  title: "Dot Matrix",
  blurb: "The carriage crosses tractor paper as dotted lines feed upward. A completed job prints a check; a failed one jams the sheet.",
  looks: [{
    name: "dotmatrix",
    label: "Dot Matrix",
    note: "a scanning print head and paper that feeds between passes",
    art: dotmatrix,
  }],
}

